const ctx = $input.first().json;
const clamp = (n) => Math.max(0, Math.min(100, Number.isFinite(n) ? n : 0));
const freshnessScore = (days, halfLife) => days === null || days === undefined ? 50 : Math.round(100 * Math.pow(0.5, Math.max(0, days) / halfLife));
const scoreOne = (lead) => {
  const reasons = [];
  let identity = clamp((lead.identity ?? lead.company_identity_confidence ?? 0) * 100);
  if (lead.ambiguity_status === 'ambiguous') { identity = Math.min(identity, 55); reasons.push('identity_ambiguous'); }
  let source_quality = clamp((lead.source_quality ?? 0.7) * 100);
  if (lead.fallback_deduplication_used) { source_quality -= 10; reasons.push('fallback_deduplication'); }
  if ((lead.required_fields_ratio ?? 1) < 0.7) { source_quality -= 12; reasons.push('incomplete_offer_data'); }
  source_quality = clamp(source_quality);
  const f = lead.freshness_days || {};
  const freshnessParts = { offers: freshnessScore(f.offers, 7), sirene: freshnessScore(f.sirene, 90), health: freshnessScore(f.health, 180) };
  const freshness = Math.round((freshnessParts.offers * 0.5) + (freshnessParts.sirene * 0.35) + (freshnessParts.health * 0.15));
  if ((f.offers ?? 0) > 30) reasons.push('stale_offer_source');
  if ((f.sirene ?? 0) > 180) reasons.push('stale_sirene_source');
  const classification = clamp((lead.deterministic_classification ?? lead.classification ?? 0.7) * 100);
  if (classification < 55) reasons.push('classification_low_confidence');
  let enrichment = lead.sirene_available ? 80 : 40;
  if (!lead.pappers_available) reasons.push('pappers_absent_neutral');
  if (lead.health_conflict) { enrichment = Math.min(enrichment, 50); reasons.push('health_conflict'); }
  let confidence = Math.round(identity * 0.35 + source_quality * 0.20 + freshness * 0.20 + classification * 0.15 + enrichment * 0.10);
  if (lead.health_conflict) confidence = Math.min(confidence, 50);
  const breakdown = { identity, source_quality, freshness, freshnessParts, classification, enrichment };
  return { ...lead, confidence_version: ctx.confidence_version, confidence, freshness, priority_export_allowed: confidence >= ctx.minimum_priority_export_confidence, confidence_breakdown_json: JSON.stringify(breakdown), confidence_reasons_json: JSON.stringify([...new Set(reasons)]), confidence_updated_at: ctx.now_utc };
};
return (ctx.leads || []).map((json) => ({ json: scoreOne(json) }));
